// Allowlist (again — Alertmanager already filters), dedupe and a rate cap for one
// Alertmanager notification group. State is only written by `Remember`, after a
// successful fire, so a failed fire is retried on the group's next notification.
// Static data only persists on production (published) runs.
const ALLOW = new Set([
  'ContainerOOMKilled', 'ContainerOOMCrashLooping', 'ContainerRestartsLooping',
  'FluxHelmReleaseNotReady', 'FluxKustomizationNotReady',
]);
// 'diagnose' = the routine reports only; 'pr' = it may open a draft PR.
const MODE = 'diagnose';
// From the routine's API trigger panel (claude.ai/code/routines). The token is the
// `Claude routine token` credential on the Fire routine node, never here.
const ROUTINE_URL = 'https://api.anthropic.com/v1/claude_code/routines/trig_REPLACE_ME/fire';
const DEDUPE_HOURS = 24;
const MAX_PER_HOUR = 6;   // routine limit is 30/h; this keeps a storm off the 5h usage window

const body = $input.first().json.body ?? {};
if (body.status !== 'firing') return [];
const alerts = (body.alerts ?? []).filter(a => a.status === 'firing' && ALLOW.has(a.labels?.alertname));
if (!alerts.length) return [];

const g = body.groupLabels ?? {};
const key = `${g.alertname ?? alerts[0].labels.alertname}|${g.namespace ?? ''}`;
const state = $getWorkflowStaticData('global');
const now = Date.now();
if (now - (state.fired?.[key] ?? 0) < DEDUPE_HOURS * 36e5) return [];
const recent = (state.recent ?? []).filter(t => now - t < 36e5);
if (recent.length >= MAX_PER_HOUR) {
  throw new Error(`Rate cap (${MAX_PER_HOUR}/h) reached, skipped ${key}`);
}

return [{ json: {
  key, mode: MODE, routineUrl: ROUTINE_URL, groupLabels: g,
  alerts: alerts.slice(0, 10).map(a => ({
    labels: a.labels, annotations: a.annotations, startsAt: a.startsAt,
    generatorURL: a.generatorURL, fingerprint: a.fingerprint,
  })),
} }];

// Evidence to gather. Label values come from alerts, so only plain values are
// spliced into PromQL/LogQL.
const g = $input.first().json;
const safe = v => (typeof v === 'string' && /^[A-Za-z0-9_.:-]{1,128}$/.test(v)) ? v : null;
const a0 = g.alerts[0].labels;
const ns = safe(a0.namespace);
const THANOS = 'http://thanos-query-frontend.monitoring.svc.cluster.local:9090/api/v1/query';
const LOKI = 'http://loki-gateway.monitoring.svc.cluster.local/loki/api/v1/query_range';
const out = [];
const prom = (label, query) => out.push({ json: { kind: 'prom', label, url: THANOS, params: { query } } });
const end = new Date();
const loki = (label, query, limit) => out.push({ json: { kind: 'loki', label, url: LOKI, params: {
  query, limit, direction: 'backward',
  start: new Date(end - 36e5).toISOString(), end: end.toISOString(),
} } });

// The rule's own expression, from Prometheus' generatorURL (?g0.expr=...).
try {
  const expr = new URL(g.alerts[0].generatorURL).searchParams.get('g0.expr');
  if (expr) prom('alert expression, evaluated now', expr);
} catch {}

const containers = [...new Set(g.alerts.map(a => safe(a.labels.container)).filter(Boolean))].slice(0, 3);
if (ns) for (const c of containers) {
  const sel = `namespace="${ns}",container="${c}"`;
  prom(`${c}: peak working set, 6h`, `max by (pod) (max_over_time(container_memory_working_set_bytes{${sel}}[6h]))`);
  prom(`${c}: memory limit`, `max by (pod) (kube_pod_container_resource_limits{${sel},resource="memory"})`);
  prom(`${c}: memory request`, `max by (pod) (kube_pod_container_resource_requests{${sel},resource="memory"})`);
  prom(`${c}: restarts, 6h`, `sum by (pod) (increase(kube_pod_container_status_restarts_total{${sel}}[6h]))`);
  prom(`${c}: last termination reason`, `kube_pod_container_status_last_terminated_reason{${sel}} == 1`);
}

const FILTER = '|~ "(?i)(error|fail|fatal|panic|oom|killed|back-?off|exceeded|denied|timeout|invalid)"';
if (ns) loki(`pod logs + events in ${ns}, 1h, filtered`, `{namespace="${ns}"} ${FILTER}`, 150);
const name = safe(a0.name);
if (name && a0.alertname.startsWith('Flux')) {
  loki(`flux-system controller logs mentioning ${name}, 1h`, `{namespace="flux-system"} |= "${name}"`, 60);
}
if (!out.length) prom('no evidence query applies', 'vector(0)');
return out;

// The routine's input. It goes to Anthropic and its contents may end up in a PUBLIC
// PR, so log lines are redacted and everything is capped below the 65,536-char limit.
const LIMIT = 60000;
const g = $('Gate').first().json;
const qs = $('Queries').all().map(i => i.json);
const rs = $('Query').all().map(i => i.json);

const REDACT = [
  [/\b(?:sk-ant-[\w-]{10,}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_\w{20,}|AKIA[0-9A-Z]{16}|xox[abpr]-[\w-]{10,})/g, '[REDACTED]'],
  [/\beyJ[\w-]{8,}\.[\w-]{8,}\.[\w-]{8,}/g, '[REDACTED-JWT]'],
  [/\b(bearer|basic)\s+[\w.~+\/=-]{8,}/gi, '$1 [REDACTED]'],
  [/((?:pass(?:word|wd)?|secret|token|api[_-]?key|access[_-]?key|authorization|cookie|session)["']?\s*[:=]\s*)("[^"]*"|'[^']*'|\S+)/gi, '$1[REDACTED]'],
  [/(:\/\/)[^\s\/:@]+:[^\s\/@]+@/g, '$1[REDACTED]@'],
];
const redact = s => REDACT.reduce((t, [re, to]) => t.replace(re, to), String(s));

const metrics = [], logs = [];
qs.forEach((q, i) => {
  const r = rs[i] ?? {};
  if (q.kind === 'prom') {
    const res = r.data?.result ?? [];
    const lines = r.error ? [`(query failed: ${r.error.message ?? r.error})`]
      : res.length ? res.slice(0, 20).map(s => {
          const { __name__, ...m } = s.metric ?? {};
          return `${JSON.stringify(m)} ${s.value?.[1]}`;
        })
      : ['(no series)'];
    metrics.push(`## ${q.label}\nquery: ${q.params.query}\n${lines.join('\n')}`);
  } else {
    const rows = (r.data?.result ?? []).flatMap(s =>
      (s.values ?? []).map(([ts, line]) => [ts, s.stream?.pod ?? s.stream?.job ?? '', line]));
    rows.sort((a, b) => (a[0] < b[0] ? 1 : -1));
    const lines = r.error ? [`(query failed: ${r.error.message ?? r.error})`]
      : rows.length ? rows.map(([ts, src, line]) =>
          `${new Date(Number(ts) / 1e6).toISOString()} ${src} ${redact(line).slice(0, 400)}`)
      : ['(no lines)'];
    logs.push(`## ${q.label}\nquery: ${q.params.query}\n${lines.join('\n')}`);
  }
});

const commits = $('Recent commits').all().map(i => i.json).filter(c => c.sha)
  .map(c => `${c.sha.slice(0, 7)} ${c.commit?.author?.date ?? ''} ${(c.commit?.message ?? '').split('\n')[0]}`);

const head = [
  `MODE: ${g.mode}`,
  `ALERT GROUP: ${g.key}`,
  '',
  '--- ALERTS (Alertmanager webhook) ---',
  redact(JSON.stringify(g.alerts, null, 2)),
  '',
  '--- METRICS (Thanos, instant) ---',
  metrics.join('\n\n'),
  '',
  `--- RECENT COMMITS (kubernetes/apps/${g.alerts[0].labels.namespace ?? '?'}) ---`,
  commits.join('\n') || '(none found)',
  '',
  '--- LOGS + EVENTS (Loki, newest first, secrets redacted) ---',
].join('\n');
let text = head + '\n' + logs.join('\n\n');
if (text.length > LIMIT) text = text.slice(0, LIMIT - 40) + '\n[... truncated to fit the payload limit]';
return [{ json: { text, chars: text.length } }];

// Records the fire so the same group is not re-sent for 24h and counts toward the cap.
const g = $('Gate').first().json;
const state = $getWorkflowStaticData('global');
const now = Date.now();
state.fired = Object.fromEntries(Object.entries(state.fired ?? {}).filter(([, t]) => now - t < 7 * 864e5));
state.fired[g.key] = now;
state.recent = [...(state.recent ?? []).filter(t => now - t < 36e5), now];
return [{ json: { key: g.key, mode: g.mode, session: $input.first().json.claude_code_session_url ?? null } }];
